```js
// Рекурсия: читается лучше всего на дереве
function countNodes(node) {
  return 1 + node.children.reduce((sum, child) => sum + countNodes(child), 0);
}

// То же циклом с явным стеком — глубина ограничена только памятью
function countNodesIterative(root) {
  const stack = [root];
  let count = 0;
  while (stack.length) {
    const node = stack.pop();
    count++;
    stack.push(...node.children);
  }
  return count;
}
```

