  private readonly cdr = inject(ChangeDetectorRef);
  value = 0;

  ngOnInit() {
    this.cdr.detach(); // исключили из общего обхода
    const loop = () => {
      this.value = read();
      this.cdr.detectChanges(); // обновляем сами, раз в кадр
      this.frame = requestAnimationFrame(loop);
    };
    loop();
  }

  ngOnDestroy() { cancelAnimationFrame(this.frame); }
}

// Данные пришли из колбэка сторонней библиотеки
thirdParty.on("data", (d) => {
  this.data = d;
  this.cdr.markForCheck(); // иначе экран не обновится
});
